def finalise_response(case: dict[str, Any], request: dict[str, Any]) -> dict[str, Any]:
    """Return the canned envelope with the two run-scoped fields applied.

    `request` is overwritten with what was actually supplied, because the
    contract defines that field as the harness's own request echoed back;
    `provenance.generated_utc` is stamped with the wall clock, matching the real
    emitter and giving the replay-equality rule (CR-6) something to exclude.
    """
    envelope = copy.deepcopy(case["response"])
    envelope["request"] = request
    if isinstance(envelope.get("provenance"), dict):
        envelope["provenance"]["generated_utc"] = (
            datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        )
    return envelope


def _emit(payload: Any, output: Path | None) -> None:
    text = json.dumps(payload, indent=2) + "\n"
    if output:
        output.write_text(text, "utf-8")
    else:
        sys.stdout.write(text)


def _fail_contract(error_envelope: dict[str, Any]) -> int:
    sys.stderr.write(json.dumps(error_envelope, indent=2) + "\n")
    return EXIT_CONTRACT_ERROR


def _read_request(args: argparse.Namespace) -> dict[str, Any] | dict[str, Any]:
    """Parse --request-json / --request-file, or return the bad_request the real
    emitter would return for unparseable or non-object request text."""
    if args.request_file:
        raw = Path(args.request_file).read_text("utf-8")
    elif args.request_json:
        raw = args.request_json
    else:
        raw = "{}"
    try:
        request = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError(f"request is not valid JSON: {exc}") from exc
    if not isinstance(request, dict):
        raise ValueError("request must be a JSON object.")
    return request


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="stub_emitter.py",
        description="Stub deterministic evidence emitter (contract v0.2.0).",
    )
    parser.add_argument("--question-id")
    parser.add_argument("--request-json")
    parser.add_argument("--request-file")
    parser.add_argument("--output")
    parser.add_argument("--list-questions", action="store_true")
    parser.add_argument("--input-catalog", action="store_true")
    parser.add_argument("--school-directory", action="store_true")
    parser.add_argument("--school-search")
    parser.add_argument("--directory-limit", type=int, default=25)
    return parser


def run_school_directory(bundle: dict[str, Any], search: str | None, limit: int) -> dict:
    """Filter the canned directory envelope and return it with updated request metadata."""
    directory_envelope = bundle["preflight"]["school_directory"]
    records = list(directory_envelope["records"])
    if search:
        needle = search.casefold()
        records = [r for r in records if needle in r["school_name"].casefold()]
    if limit is not None and limit >= 0:
        records = records[:limit]
    result = copy.deepcopy(directory_envelope)
    result["records"] = records
    result["request"] = {
        "school_search": search,
        "school_sector": [],
        "school_type": [],
        "limit": limit,
    }
    if isinstance(result.get("provenance"), dict):
        result["provenance"]["generated_utc"] = (
            datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        )
    return result


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    output = Path(args.output) if args.output else None

    try:
        bundle = load_bundle()
    except NoFixture as exc:
        sys.stderr.write(f"stub emitter: {exc}\n")
        return EXIT_NO_FIXTURE

    if args.list_questions:
        _emit(sorted(registry_question_ids()), output)
        return EXIT_OK

    if args.input_catalog:
        _emit(bundle["preflight"]["input_catalog"], output)
        return EXIT_OK

    if args.school_directory:
        _emit(run_school_directory(bundle, args.school_search, args.directory_limit), output)
        return EXIT_OK

    if not args.question_id:
        return _fail_contract(
            {
                "contract_version": CONTRACT_VERSION,
                "error_kind": "bad_request",
                "error": "--question-id is required unless a preflight interface is requested.",
            }
        )

    try:
        request = _read_request(args)
    except (ValueError, OSError) as exc:
        return _fail_contract(
            {
                "contract_version": CONTRACT_VERSION,
                "error_kind": "bad_request",
                "error": str(exc),
            }
        )

    try:
        case = select_case(bundle, args.question_id, request)
    except NoFixture as exc:
        sys.stderr.write(f"stub emitter: {exc}\n")
        return EXIT_NO_FIXTURE

    if "error" in case:
        return _fail_contract(case["error"])

    _emit(finalise_response(case, request), output)
    return EXIT_OK


if __name__ == "__main__":
    raise SystemExit(main())
